#!/bin/bash
# ICEWS18 second benchmark: the stages that need the GPU (MPS) or the reader, on the questions generated by
# scripts/17_generate_questions.py (cache/icews18/questions.json: 6,000 test, questions_dev.json: 1,200 dev).
# Start only after the MultiTQ Qwen run has finished; every GPU step first checks that no reader is running.
# Each step is skipped when its output exists (resumable). CPU work is capped at 2 threads.
#
#   caffeinate -i bash logs/run_icews18.sh            # everything (about 6-7 h; the reader is most of it)
#   caffeinate -i bash logs/run_icews18.sh retrieval  # R: encode, search, labels, anchors, rerank, LLM-free Hit@1
#   caffeinate -i bash logs/run_icews18.sh difficulty # D: regenerated ICEWS05-15 through the same retrieval stages
#   caffeinate -i bash logs/run_icews18.sh reader     # Q: Qwen 2,000 questions x {none, timer4, tear, tear_window}
#
# Settings are the paper's MultiTQ configuration: original questions (no rewrite exists for generated questions),
# rule v2 labels with the NER topic fallback, date parser v2, exact-match ATC, anchor grounding + equal window,
# all-mpnet-base-v2 top-1000, Qwen2.5-7B-Instruct-4bit, prompt v3, k = 15, date-unit post-processing in scoring.
cd "$(dirname "$0")/.." || exit 1
export OMP_NUM_THREADS=2 MKL_NUM_THREADS=2 OPENBLAS_NUM_THREADS=2 VECLIB_MAXIMUM_THREADS=2 NUMEXPR_NUM_THREADS=2
export HF_HUB_OFFLINE=1
P=".venv/bin/python -I"
M=".venv-mlx/bin/python -I"
DS=icews18
D=cache/$DS
TAG=rule_v2_ground_exact            # 05 appends _anydate
RTAG=${TAG}_anydate
PRED=results/qwen_icews18
SCORES=results/qwen_icews18_scores
LOG=logs/run_icews18.log
WHAT=${1:-all}
COMMON="--atc_match exact --date_granularity any --date_parser v2"

step() { echo "[$(date '+%F %T')] $1" | tee -a "$LOG"; }
guard() {   # the MultiTQ reader (or any other reader) must not share the GPU
  if pgrep -f "07_read_with_llm.py" >/dev/null || pgrep -f "run_qwen_chunks" >/dev/null; then
    echo "[$(date '+%F %T')] a Qwen reader is still running; not starting (${1:-})" | tee -a "$LOG"
    pgrep -fl "07_read_with_llm.py|run_qwen_chunks" | tee -a "$LOG"
    exit 2
  fi
}
need() { [ -f "$1" ] || { echo "missing $1 (run scripts/17_generate_questions.py first)"; exit 1; }; }
need $D/questions.json; need $D/questions_dev.json; need $D/facts.npz

retrieval() {
  guard "R1"
  [ -f $D/fact_emb.npy ] || { step "R1 encode 468,558 ICEWS18 facts (MPS, ~30 min)"; $P scripts/02_encode_facts.py --dataset $DS || exit 1; }
  guard "R2"
  [ -f $D/top1000_ids.npy ] || { step "R2 search test"; $P scripts/03_search.py --dataset $DS --threads 2 || exit 1; }
  [ -f $D/top1000_dev_ids.npy ] || { step "R2 search dev"; $P scripts/03_search.py --dataset $DS \
      --questions questions_dev.json --suffix _dev --threads 2 || exit 1; }
  guard "R3"
  [ -f $D/topic_ner_all.json ] || { step "R3 NER topic fallback (test)"; $P scripts/04_label_slots.py --dataset $DS \
      --method ner --labels all --verify_sample 0 --torch_threads 2 || exit 1; }
  [ -f $D/topic_ner_all_dev.json ] || { step "R3 NER topic fallback (dev)"; $P scripts/04_label_slots.py --dataset $DS \
      --method ner --labels all --verify_sample 0 --torch_threads 2 --questions questions_dev.json --suffix _dev || exit 1; }
  step "R4 rule v2 labels with NER fallback"
  $P scripts/04_label_slots.py --dataset $DS --method rule --rule_version v2 --ner_topics $D/topic_ner_all.json \
      --out $D/slots_rule_v2.json || exit 1
  $P scripts/04_label_slots.py --dataset $DS --method rule --rule_version v2 --questions questions_dev.json \
      --ner_topics $D/topic_ner_all_dev.json --out $D/slots_rule_v2_dev.json || exit 1
  if [ ! -f $D/anchors_dev.json ]; then
    step "R5 anchor grounding (dev; CPU)"
    $P scripts/14_ground_anchors.py --dataset $DS --questions questions_dev.json --qemb q_emb_dev.npy \
        --slots $D/slots_rule_v2_dev.json --out $D/anchors_dev.json || exit 1
    mv results/${DS}_anchor_resolution.csv results/${DS}_dev_anchor_resolution.csv
  fi
  [ -f $D/anchors.json ] || { step "R5 anchor grounding (test; CPU)"; $P scripts/14_ground_anchors.py --dataset $DS \
      --slots $D/slots_rule_v2.json || exit 1; }
  step "R6 rerank test: grounding + equal window (main), and without grounding"
  [ -f $D/rerank/tear_window_${RTAG}_top30_ids.npy ] || $P scripts/05_rerank.py --dataset $DS \
      --slots $D/slots_rule_v2.json $COMMON --anchors $D/anchors.json --equal_window --sweep --tag $TAG || exit 1
  [ -f $D/rerank/tear_window_rule_v2_exact_anydate_top30_ids.npy ] || $P scripts/05_rerank.py --dataset $DS \
      --slots $D/slots_rule_v2.json $COMMON --tag rule_v2_exact || exit 1
  [ -f $D/rerank_dev/tear_window_${RTAG}_top30_ids.npy ] || $P scripts/05_rerank.py --dataset $DS \
      --questions questions_dev.json --suffix _dev --slots $D/slots_rule_v2_dev.json $COMMON \
      --anchors $D/anchors_dev.json --equal_window --tag $TAG --results_dir results/${DS}_dev --rerank_dir $D/rerank_dev || exit 1
  step "R7 LLM-free Hit@1"
  $P scripts/06_llmfree_eval.py --dataset $DS --tag $RTAG --slots $D/slots_rule_v2.json --baseline none || exit 1
  $P scripts/06_llmfree_eval.py --dataset $DS --tag rule_v2_exact_anydate --slots $D/slots_rule_v2.json --baseline none || exit 1
  $P scripts/06_llmfree_eval.py --dataset $DS --questions questions_dev.json --tag $RTAG --slots $D/slots_rule_v2_dev.json \
      --rerank_dir $D/rerank_dev --results_dir results/${DS}_dev --baseline none || exit 1
  step "R8 rule labels (with NER fallback) and full anchor grounding against the generator's record"
  $P scripts/17_generate_questions.py rulecheck --dataset $DS --slots $D/slots_rule_v2.json --anchors $D/anchors.json \
      --suffix _final || exit 1
  step "retrieval stages done"
}

difficulty() {
  # same retriever, labels, grounding and rerankers on the ICEWS05-15 questions regenerated by the generator
  # (fact embeddings are the MultiTQ ones, symlinked: no fact encoding)
  local R=icews0515_regen C=cache/icews0515_regen
  need $C/questions.json
  guard "D1"
  [ -f $C/top1000_ids.npy ] || { step "D1 search regenerated ICEWS05-15"; $P scripts/03_search.py --dataset $R --threads 2 || exit 1; }
  guard "D2"
  [ -f $C/topic_ner_all.json ] || { step "D2 NER topic fallback"; $P scripts/04_label_slots.py --dataset $R --method ner \
      --labels all --verify_sample 0 --torch_threads 2 || exit 1; }
  $P scripts/04_label_slots.py --dataset $R --method rule --rule_version v2 --ner_topics $C/topic_ner_all.json \
      --out $C/slots_rule_v2.json || exit 1
  [ -f $C/anchors.json ] || { step "D3 anchor grounding"; $P scripts/14_ground_anchors.py --dataset $R \
      --slots $C/slots_rule_v2.json || exit 1; }
  step "D4 rerank + LLM-free Hit@1 (with and without grounding)"
  [ -f $C/rerank/tear_window_${RTAG}_top30_ids.npy ] || $P scripts/05_rerank.py --dataset $R --slots $C/slots_rule_v2.json \
      $COMMON --anchors $C/anchors.json --equal_window --tag $TAG || exit 1
  [ -f $C/rerank/tear_window_rule_v2_exact_anydate_top30_ids.npy ] || $P scripts/05_rerank.py --dataset $R \
      --slots $C/slots_rule_v2.json $COMMON --tag rule_v2_exact || exit 1
  $P scripts/06_llmfree_eval.py --dataset $R --tag $RTAG --slots $C/slots_rule_v2.json --baseline none || exit 1
  $P scripts/06_llmfree_eval.py --dataset $R --tag rule_v2_exact_anydate --slots $C/slots_rule_v2.json --baseline none || exit 1
  $P scripts/17_generate_questions.py rulecheck --dataset $R --slots $C/slots_rule_v2.json --anchors $C/anchors.json \
      --suffix _final || exit 1
  step "D5 difficulty table: MultiTQ (multitq_orig) vs regenerated ICEWS05-15 vs ICEWS18"
  $P scripts/17_generate_questions.py difficulty || exit 1
}

reader() {
  # 2,000 questions = the first 2,000 of the reader's fixed shuffle of the 6,000-question sample (all test questions,
  # 1,000 per type); settings share that order, so every prefix is paired. Before each setting, predictions are
  # copied from the settings already run where the top-15 fact list is identical (scripts/14_reuse_across_settings.py).
  [ -f $D/sample_6000.json ] || { step "Q0 reader sample"; $M scripts/07_read_with_llm.py --dataset $DS --make_sample || exit 1; }
  mkdir -p $PRED $SCORES
  local done_settings=""
  for s in none timer4 tear tear_window; do
    guard "Q $s"
    if [ -n "$done_settings" ]; then
      $P scripts/14_reuse_across_settings.py --dataset $DS --tag $RTAG --pred_dir $PRED --target "$s" \
          --sources "${done_settings#,}" --start 0 --end 2000 --prompt v3
    fi
    step "Q reader $s (2,000 questions)"
    $M scripts/07_read_with_llm.py --dataset $DS --setting "$s" --tag $RTAG --questions questions.json \
        --sample sample_6000.json --prompt v3 --k 15 --batch 1 --start 0 --end 2000 --pred_dir $PRED \
        2>&1 | grep -v -i warning | tail -1 | tee -a "$LOG"
    done_settings="$done_settings,$s"
  done
  step "Q score (Hit@1, McNemar / bootstrap vs none)"
  $P scripts/08_score_reader.py --pred_dir $PRED --results_dir $SCORES --baseline none_$RTAG | tee -a "$LOG"
}

case "$WHAT" in
  retrieval) retrieval ;;
  difficulty) difficulty ;;
  reader) reader ;;
  all) retrieval; difficulty; reader ;;
  *) echo "usage: $0 [all|retrieval|difficulty|reader]"; exit 1 ;;
esac
step "run_icews18.sh $WHAT finished"
